-- Alerts by email too (#1066, the owner, 17 Nov): Settings > Club gets "Also send alerts by email" and up to five
-- addresses, and every alert that goes to the alert WhatsApp number also goes by email, through Resend, from the
-- alert-email outbox consumer. Never from the practice venue; only an alert's kind in words, no member's details. The
-- consumer is not scheduled here: it runs once its secrets are set (docs/runbooks/ci-and-release.md, decision 0689).
-- Changing either setting raises the usual settings alert. Generated by gen1066.py.

-- At most five addresses, each its own entry and one plausible (the console checks them properly first), and at least
-- one while it is on.
-- Checked inline: super admins update venue_config directly, and they call no private function.
alter table public.venue_config
  add column alert_email_on boolean not null default false,
  add column alert_emails text[] not null default '{}'
    check (cardinality(alert_emails) <= 5
           and array_position(alert_emails, null) is null
           and char_length(array_to_string(alert_emails, chr(10))) <= 5 * 255
           and (cardinality(alert_emails) = 0
                or (cardinality(regexp_split_to_array(array_to_string(alert_emails, chr(10)), chr(10))) = cardinality(alert_emails)
                    and array_to_string(alert_emails, chr(10))
                        ~ '^[^@\s]{1,64}@[^@\s]{1,190}\.[^@\s]{1,63}(?:\n[^@\s]{1,64}@[^@\s]{1,190}\.[^@\s]{1,63})*$'))),
  add constraint venue_config_alert_email_needs_an_address check (not alert_email_on or cardinality(alert_emails) >= 1);

-- The venue's alert addresses for an alert raised within the day while email alerts are on; no row otherwise, and never
-- the practice venue. For the alert-email consumer, through the service role only.
create function private.alert_email_recipients(p_venue_id uuid, p_alert_id uuid)
returns table (alert_emails text[])
language sql
stable
security definer
set search_path = ''
as $$
  select c.alert_emails
  from public.alert a
  join public.venue v on v.id = a.venue_id and not v.is_practice
  join public.venue_config c on c.venue_id = a.venue_id and c.alert_email_on
  where a.id = p_alert_id and a.venue_id = p_venue_id and a.raised_at > now() - interval '1 day';
$$;
create function public.alert_email_recipients(p_venue_id uuid, p_alert_id uuid)
returns table (alert_emails text[])
language sql
set search_path = ''
as $$ select * from private.alert_email_recipients(p_venue_id, p_alert_id); $$;
revoke all on function private.alert_email_recipients(uuid, uuid), public.alert_email_recipients(uuid, uuid) from public, anon, authenticated;
grant execute on function private.alert_email_recipients(uuid, uuid), public.alert_email_recipients(uuid, uuid) to service_role;

-- A change to the email alerts raises the settings alert, as a change to the alert number does.
CREATE OR REPLACE FUNCTION private.alert_venue_config_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_alert_id uuid;
  v_fields text[] := array_remove(array[
    case when new.upi_vpa is distinct from old.upi_vpa then 'upi_vpa' end,
    case when new.upi_payee_name is distinct from old.upi_payee_name then 'upi_payee_name' end,
    case when new.bank_name is distinct from old.bank_name then 'bank_name' end,
    case when new.bank_account_name is distinct from old.bank_account_name then 'bank_account_name' end,
    case when new.bank_account_number is distinct from old.bank_account_number then 'bank_account_number' end,
    case when new.bank_ifsc is distinct from old.bank_ifsc then 'bank_ifsc' end,
    case when new.alert_whatsapp is distinct from old.alert_whatsapp then 'alert_whatsapp' end,
    case when new.alert_email_on is distinct from old.alert_email_on then 'alert_email_on' end,
    case when new.alert_emails is distinct from old.alert_emails then 'alert_emails' end,
    case when new.contact_phone is distinct from old.contact_phone then 'contact_phone' end,
    case when new.contact_whatsapp is distinct from old.contact_whatsapp then 'contact_whatsapp' end
  ], null);
begin
  if cardinality(v_fields) > 0 and (select auth.uid()) is not null then
    v_alert_id := private.raise_alert(new.venue_id, 'venue.config_changed', jsonb_build_object('fields', to_jsonb(v_fields)));
    if 'alert_whatsapp' = any (v_fields) and old.alert_whatsapp is not null then
      insert into private.alert_previous_number (alert_id, alert_whatsapp) values (v_alert_id, old.alert_whatsapp);
    end if;
  end if;
  return new;
end;
$function$;

-- The alert addresses are personal data: Activity shown to investors leaves them out.
CREATE OR REPLACE FUNCTION private.is_shareable_audit_row(p_entity text, p_before jsonb, p_after jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select p_entity in ('setting', 'tier', 'tier_feature', 'table_type', 'game_table', 'table_run', 'chip_denomination', 'blind_structure',
                      'tournament_template', 'tournament', 'promotion', 'promotion_rule', 'promotion_grant', 'bonus_grant',
                      'fnb_item', 'sop', 'sop_version', 'site_block', 'site_page', 'site_revision', 'cage_shift',
                      'chip_inventory_count', 'chip_inventory_line', 'ledger_account', 'academy_batch', 'device', 'tablet_assignment',
                      'down_count', 'dealer_down', 'hand', 'high_hand_claim', 'jackpot_event', 'visit', 'waitlist_entry', 'credit_line',
                      'venue', 'alert')
     and not exists (
       select 1 from unnest(array[p_before, p_after]) r
       where coalesce(r ?| array['phone', 'full_name', 'address', 'signature_svg', 'buyer_name', 'buyer_gstin', 'pan', 'date_of_birth',
                                 'city', 'occupation', 'alert_whatsapp', 'alert_emails', 'bank_account_name', 'bank_account_number', 'bank_ifsc', 'upi_vpa',
                                 'upi_payee_name', 'staff_ip_allowlist', 'company_name', 'company_gstin', 'signatory_name'], false));
$function$;

-- The super admins' configuration, with the email alerts.
create or replace view public.venue_config_detail with (security_invoker = true) as
select venue_id, legal_name, gstin, address, upi_payee_name, upi_vpa, bank_name, bank_account_name, bank_account_number, bank_ifsc,
       invoice_prefix, logo_path, alert_whatsapp, created_at, updated_at, tan, sac_club_services, signatory_name, signatory_designation,
       tv_pairing_window_only, tv_pairing_window_at, contact_phone, contact_whatsapp, alert_email_on, alert_emails
from private.venue_config_detail_rows();
